def is_palindrome(s):
    cleaned = ''.join(char for char in s.lower() if char.isalnum())
    return cleaned == cleaned[::-1]

def average(nums):
    if not nums:
        return None
    return sum(nums) / len(nums)

def safe_divide(a, b):
    if b == 0:
        raise ValueError('division by zero')
    return a / b

def flatten(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result
